class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        memo = {}

        def best(i, mask):
            if i == n:
                return 0
            key = (i, mask)
            if key in memo:
                return memo[key]
            res = best(i + 1, mask)  # skip this row
            for v in set(grid[i]):
                if not (mask >> v) & 1:
                    cand = v + best(i + 1, mask | (1 << v))
                    if cand > res:
                        res = cand
            memo[key] = res
            return res

        return best(0, 0)
