class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        vals = set()
        for row in grid:
            for x in row:
                vals.add(x)
        vals = sorted(vals)
        vid = {v: i for i, v in enumerate(vals)}
        m = len(vals)
        # nodes: source 0, rows 1..n, values n+1..n+m, sink n+m+1
        N = n + m + 2
        S, T = 0, N - 1
        graph = [[] for _ in range(N)]

        def add_edge(u, v, cap, cost):
            graph[u].append([v, cap, cost, len(graph[v])])
            graph[v].append([u, 0, -cost, len(graph[u]) - 1])

        for i in range(n):
            add_edge(S, 1 + i, 1, 0)
            for x in grid[i]:
                add_edge(1 + i, n + 1 + vid[x], 1, -x)
        for j in range(m):
            add_edge(n + 1 + j, T, 1, 0)

        total = 0
        INF = float('inf')
        while True:
            dist = [INF] * N
            inq = [False] * N
            prev = [None] * N
            dist[S] = 0
            # Bellman-Ford / SPFA
            from collections import deque
            q = deque([S])
            inq[S] = True
            while q:
                u = q.popleft()
                inq[u] = False
                for idx, e in enumerate(graph[u]):
                    v, cap, cost, _ = e
                    if cap > 0 and dist[u] + cost < dist[v]:
                        dist[v] = dist[u] + cost
                        prev[v] = (u, idx)
                        if not inq[v]:
                            inq[v] = True
                            q.append(v)
            if dist[T] == INF or dist[T] >= 0:
                break
            total += -dist[T]
            # augment by 1
            v = T
            while v != S:
                u, idx = prev[v]
                e = graph[u][idx]
                e[1] -= 1
                graph[v][e[3]][1] += 1
                v = u
        return total
