from functools import lru_cache

class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        m = len(grid)
        # Map values to bit positions in a compact way
        vals = sorted({v for row in grid for v in row})
        idx = {v: i for i, v in enumerate(vals)}

        # Pre-process rows: unique values per row
        rows = [sorted({idx[v] for v in row}) for row in grid]

        @lru_cache(maxsize=None)
        def dp(r, mask):
            # returns max additional score from rows r.. given used mask; -inf if nothing picked is required
            if r == m:
                return 0
            best = dp(r + 1, mask)  # skip this row
            for c in rows[r]:
                if not (mask >> c) & 1:
                    gain = vals[c] + dp(r + 1, mask | (1 << c))
                    if gain > best:
                        best = gain
            return best

        return dp(0, 0)
