class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        # rows_with[v] = set of row indices containing value v
        rows_with = {}
        for r in range(n):
            for v in set(grid[r]):
                rows_with.setdefault(v, []).append(r)

        NEG = float('-inf')
        full = 1 << n
        dp = [NEG] * full
        dp[0] = 0

        for v in sorted(rows_with.keys()):
            new_dp = dp[:]
            for mask in range(full):
                if dp[mask] == NEG:
                    continue
                for r in rows_with[v]:
                    if not (mask >> r) & 1:
                        nm = mask | (1 << r)
                        val = dp[mask] + v
                        if val > new_dp[nm]:
                            new_dp[nm] = val
            dp = new_dp

        best = max(dp)
        return int(best)

