import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 5))
    m = draw(st.integers(1, 5))
    mode = draw(st.integers(0, 2))
    if mode == 0:
        # small value range to force duplicates
        val = st.integers(1, 4)
    elif mode == 1:
        # extremes of the allowed range
        val = st.sampled_from([1, 2, 99, 100])
    else:
        val = st.integers(1, 100)
    grid = [draw(st.lists(val, min_size=m, max_size=m)) for _ in range(n)]
    return json.dumps(grid)

def validate(inp):
    try:
        grid = json.loads(inp)
    except Exception:
        return False
    if not isinstance(grid, list) or not (1 <= len(grid) <= 10):
        return False
    if not all(isinstance(r, list) for r in grid):
        return False
    if any(len(r) != len(grid[0]) for r in grid):
        return False
    if not (1 <= len(grid[0]) <= 10):
        return False
    for r in grid:
        for x in r:
            if type(x) is not int or not (1 <= x <= 100):
                return False
    return True

def ref(inp):
    grid = json.loads(inp)
    n = len(grid)
    m = len(grid[0])

    # Exhaustive: for each row choose skip or one column; values must be distinct.
    def rec(i, used):
        if i == n:
            return 0
        best = rec(i + 1, used)  # skip this row
        for j in range(m):
            v = grid[i][j]
            if v not in used:
                cand = v + rec(i + 1, used | {v})
                if cand > best:
                    best = cand
        return best

    # Grid is nonempty and all values are positive, so the best selection
    # (which is nonempty) has positive score and this equals the required answer.
    return json.dumps(rec(0, frozenset()))
